/*selectMasterLogisRateMngList*/ SELECT X.AGENT, X.AGENT_NAME, X.AGENT_IRS_NO, X.BUYER, X.BUYER_NAME, X.BUYER_IRS_NO, X.LOGIS_RATE, X.AGENT_USER_NAME, X.LOGIS_CNT, X.START_DATE, X.END_DATE, X.ADD_DATE, X.ADD_USER_ID, X.ADD_USER_NAME, X.CHANGE_DATE, X.CHANGE_USER_ID, X.CHANGE_USER_NAME, X.REMARK, X.KEP_USER_NAME, DECODE(X.EXP_FLAG,'N','국내','해외') AS EXP_FLAG FROM ( SELECT A.AGENT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_NAME, A.AGENT_IRS_NO, A.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME, A.BUYER_IRS_NO, A.LOGIS_RATE, A.AGENT_USER_NAME, '0' AS LOGIS_CNT, TO_CHAR(TO_DATE(A.START_DATE, 'YYYYMMDD'), 'YYYY/MM/DD') AS START_DATE, A.END_DATE, A.ADD_DATE, A.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, A.CHANGE_DATE, A.CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME, A.REMARK, A.KEP_USER_NAME, A.EXP_FLAG FROM LOGIS_RATE_MNG A WHERE 1=1 AND STATUS IN ('C', 'R') AND NOT EXISTS ( SELECT 'X' FROM KEP_LOGISTIC_FEE_MNG WHERE A.AGENT = AGENT AND A.EXP_FLAG = EXP_FLAG )
AND A.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND REPLACE(A.AGENT_IRS_NO,'-','') LIKE '%'|| REPLACE(#{st_agent_irs_no},'-','') ||'%'
UNION ALL
SELECT A.AGENT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_NAME, A.AGENT_IRS_NO, A.BUYER, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS BUYER_NAME, A.BUYER_IRS_NO, A.LOGIS_RATE, A.AGENT_USER_NAME, '8' AS LOGIS_CNT, TO_CHAR(TO_DATE(A.START_DATE, 'YYYYMMDD'), 'YYYY/MM/DD') AS START_DATE, A.END_DATE, A.ADD_DATE, A.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, A.CHANGE_DATE, A.CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME, A.REMARK, A.KEP_USER_NAME, A.EXP_FLAG FROM LOGIS_RATE_MNG A WHERE 1=1 AND STATUS IN ('C', 'R') AND EXISTS ( SELECT 'X' FROM KEP_LOGISTIC_FEE_MNG WHERE A.AGENT = AGENT AND A.EXP_FLAG = EXP_FLAG )
AND A.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND REPLACE(A.AGENT_IRS_NO,'-','') LIKE '%'|| REPLACE(#{st_agent_irs_no},'-','') ||'%'
) X ORDER BY X.AGENT, X.ADD_DATE

mapper.update:

/* updateMasterCmClLogisRateMngList */
UPDATE LOGIS_RATE_MNG
SET 
	 STATUS = 'R'
	,LOGIS_RATE = #{LOGIS_RATE}
	,END_DATE = #{END_DATE}
	,REMARK = REMARK || '@@' || #{REMARK}			
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}
	,CHANGE_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
WHERE 1=1
AND AGENT = #{AGENT}
AND BUYER = #{BUYER}
AND EXP_FLAG = DECODE(#{EXP_FLAG},'국내','N','Y')


/* deleteMasterCmClLogisRateMngList */
UPDATE LOGIS_RATE_MNG
SET  
	 STATUS = 'D'				
	,CHANGE_DATE = SYSDATE
	,CHANGE_USER_ID = #{st_user_id}
	,CHANGE_USER_NAME = (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id})
	,REMARK = REMARK || '@@' || #{REMARK}
WHERE 1=1
AND AGENT = #{AGENT}
AND BUYER = #{BUYER}
AND EXP_FLAG = DECODE(#{EXP_FLAG},'국내','N','Y')

