	 /*selectMasterLogisRateMngFeeList*/
    	SELECT           
    			(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER) AS BUYER_NAME,
    			BUYER_ITEM_NO,
    			LOGISTICS_FEE || '%' AS LOGISTICS_FEE,
    			TO_CHAR(TO_DATE(END_DATE, 'YYYYMM'), 'YYYY/MM') AS END_DATE,		    			
    			REASON,
    			ADD_USER_NAME,
    			TO_CHAR(ADD_DATE, 'YY/MM/DD') AS ADD_DATE,
    			LOGIS_RATE_STATUS,
    			(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'LGST' AND CODE = LOGIS_RATE_STATUS AND FLAG = 'Y') AS LOGIS_RATE_STATUS_TEXT	    			                 
				FROM KEP_LOGISTIC_FEE_MNG
				WHERE 1=1
				AND AGENT = #{st_agent}
				AND EXP_FLAG = #{st_exp_flag}


		   		 AND BUYER = #{st_buyer}


		   		 AND BUYER_ITEM_NO = #{st_buyer_item_no}


		   		 AND ADD_USER_NAME = #{st_add_user_name}

				ORDER BY 1, ADD_DATE
